<?php require '../includes/auth.php';require_role('buyer');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=post('name');if(strlen($name)<2)flash('error','Name is required.');else{$pdo->prepare('UPDATE users SET name=?,phone=? WHERE id=?')->execute([$name,post('phone'),user()['id']]);$_SESSION['user']['name']=$name;flash('success','Profile updated.');}redirect('buyer/profile.php');}$s=$pdo->prepare('SELECT * FROM users WHERE id=?');$s->execute([user()['id']]);$u=$s->fetch();$pageTitle='My profile';require '../includes/header.php';?><div class="page-title"><p class="eyebrow">ACCOUNT</p><h1>My profile</h1></div><form class="card-form narrow" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Name<input name="name" value="<?=e($u['name'])?>" required></label><label>Email<input value="<?=e($u['email'])?>" disabled></label><label>Phone<input name="phone" value="<?=e($u['phone'])?>"></label><button>Save changes</button></form><?php require '../includes/footer.php'; ?>
